Status Battery::dispatch(uint8_t cmd_id, std::span<const uint8_t> args, Reply &reply)
{
    switch (cmd_id) {
    case kCmdRead: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        const auto r = read();
        if (!r) {
            return std::unexpected(r.error());
        }
        encode(*r, reply.fields());
        // Fields beyond the caller's buffer (realtime or bulk): FAILED with no fields, never truncated ones.
        if (reply.fields().overflow()) {
            reply.clear();
            return std::unexpected(Err::failed);
        }
        return {};
    }
    case kCmdCalibrate: {
        const auto a = decode_battery_calibrate_args(args);
        if (!a || !valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        const auto r = calibrate(*a);
        if (!r) {
            return std::unexpected(r.error());
        }
        encode(*r, reply.fields());
        // Fields beyond the caller's buffer (realtime or bulk): FAILED with no fields, never truncated ones.
        if (reply.fields().overflow()) {
            reply.clear();
            return std::unexpected(Err::failed);
        }
        return {};
    }
    case kCmdResetCalibration: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return reset_calibration();
    }
    case kCmdLoad: {
        const auto a = decode_battery_load_args(args);
        if (!a || !valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return load(*a);
    }
    case kCmdGate: {
        const auto a = decode_battery_gate_args(args);
        if (!a || !valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return gate(*a);
    }
#if FR_TEST_HOOKS
    case kCmdInject: {
        const auto a = decode_battery_inject_args(args);
        if (!a || !valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return inject(*a);
    }
#endif
    default:
        return std::unexpected(Err::unsupported);
    }
}

void Battery::report_all()
{
    report_mv(mv());
    report_percent(percent());
    report_charger(charger());
    report_level(level());
    report_load_on(load_on());
    report_gate_open(gate_open());
}

void Battery::encode_traits(fr::wire::Writer &w) const
{
    encode(traits(), w);
}

void Battery::emit_charge(const BatteryCharge &e, TimeUs at)
{
    if (sink_ == nullptr) {
        return;
    }
    uint8_t buf[BatteryCharge::kMaxSize];
    fr::wire::Writer w(buf, sizeof(buf));
    encode(e, w);
    sink_->event(port_, kEventCharge, Priority::normal, w.bytes(), at, kOrdered);
}

